our email');\n      return;\n    }\n\n    if (!password.trim() || password.length < 6) {\n      setError('Password must be at least 6 characters');\n      return;\n    }\n\n    if (mode === 'signup' && password !== confirmPassword) {\n      setError('Passwords do not match');\n      return;\n    }\n\n    if (Platform.OS !== 'web') {\n      void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);\n    }\n\n    if (mode === 'signin') {\n      signIn(email.trim(), password);\n    } else {\n      signUp(email.trim(), password);\n    }\n  }, [email, password, confirmPassword, mode, signIn, signUp]);\n\n  return (\n    <View style={styles.container}>\n      <Stack.Screen options={{ headerShown: false }} />\n      <Image\n        source={{ uri: 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=800&q=80' }}\n        style={styles.bgImage}\n        resizeMode=\"cover\"\n      />\n      <View style={styles.bgOverlay} />\n\n      <KeyboardAvoidingView\n        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}\n        style={styles.keyboardView}\n      >\n        <ScrollView\n          contentContainerStyle={[styles.scrollContent, { paddingTop: insets.top + 20 }]}\n          keyboardShouldPersistTaps=\"handled\"\n          showsVerticalScrollIndicator={false}\n        >\n          <TouchableOpacity\n            style={styles.backButton}\n            onPress={() => router.back()}\n            activeOpacity={0.7}\n            testID=\"auth-back-button\"\n          >\n            <ArrowLeft color={Colors.white} size={22} />\n          </TouchableOpacity>\n\n          <View style={styles.heroSection}>\n            <View style={styles.iconRow}>\n              <View style={styles.cloudIcon}>\n                <Cloud color={Colors.white} size={28} />\n              </View>\n              <View style={styles.syncDots}>\n                <View style={[styles.dot, styles.dotActive]} />\n                <View style={[styles.dot, styles.dotActive]} />\n                <View style={[styles.dot, styles.dotActive]} />\n              </View>\n              <View style={styles.mountainIconCircle}>\n                <Mountain color={Colors.white} size={28} />\n              </View>\n            </View>\n            <Text style={styles.heroTitle}>\n              {mode === 'signin' ? 'Welcome back' : 'Create account'}\n            </Text>\n            <Text style={styles.heroSubtitle}>\n              {mode === 'signin'\n                ? 'Sign in to sync your summit data across devices'\n                : 'Your existing summit data will be backed up automatically'}\n            </Text>\n          </View>\n\n          <View style={styles.formCard}>\n            <View style={styles.inputGroup}>\n              <View style={styles.inputWrapper}>\n                <Mail color={Colors.textMuted} size={18} />\n                <TextInput\n                  style={styles.input}\n                  placeholder=\"Email address\"\n                  placeholderTextColor={Colors.textMuted}\n                  value={email}\n                  onChangeText={setEmail}\n                  keyboardType=\"email-address\"\n                  autoCapitalize=\"none\"\n                  autoCorrect={false}\n                  returnKeyType=\"next\"\n                  onSubmitEditing={() => passwordRef.current?.focus()}\n                  testID=\"auth-email-input\"\n                />\n              </View>\n\n              <View style={styles.inputWrapper}>\n                <Lock color={Colors.textMuted} size={18} />\n                <TextInput\n                  ref={passwordRef}\n                  style={styles.input}\n                  placeholder=\"Password\"\n                  placeholderTextColor={Colors.textMuted}\n                  value={password}\n                  onChangeText={setPassword}\n                  secureTextEntry={!showPassword}\n                  returnKeyType={mode === 'signup' ? 'next' : 'done'}\n                  onSubmitEditing={() =>\n                    mode === 'signup' ? confirmRef.current?.focus() : handleSubmit()\n                  }\n                  testID=\"auth-password-input\"\n                />\n                <TouchableOpacity\n                  onPress={() => setShowPassword(!showPassword)}\n                  hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}\n                >\n                  {showPassword ? (\n                    <EyeOff color={Colors.textMuted} size={18} />\n                  ) : (\n                    <Eye color={Colors.textMuted} size={18} />\n                  )}\n                </TouchableOpacity>\n              </View>\n\n              {mode === 'signup' && (\n                <View style={styles.inputWrapper}>\n                  <Lock color={Colors.textMuted} size={18} />\n                  <TextInput\n                    ref={confirmRef}\n                    style={styles.input}\n                    placeholder=\"Confirm password\"\n                    placeholderTextColor={Colors.textMuted}\n                    value={confirmPassword}\n                    onChangeText={setConfirmPassword}\n                    secureTextEntry={!showPassword}\n                    returnKeyType=\"done\"\n                    onSubmitEditing={handleSubmit}\n                    testID=\"auth-confirm-password-input\"\n                  />\n                </View>\n              )}\n            </View>\n\n            {error ? (\n              <View style={styles.errorBox}>\n                <Text style={styles.errorText}>{error}</Text>\n              </View>\n            ) : null}\n\n            <TouchableOpacity\n              style={[styles.submitButton, isLoading && styles.submitButtonDisabled]}\n              onPress={handleSubmit}\n              disabled={isLoading}\n              activeOpacity={0.8}\n              testID=\"auth-submit-button\"\n            >\n              {isLoading ? (\n                <ActivityIndicator color={Colors.white} size=\"small\" />\n   