lor: Colors.frost,\n    borderRadius: 14,\n    paddingHorizontal: 16,\n    paddingVertical: 14,\n    gap: 12,\n    borderWidth: 1,\n    borderColor: Colors.border,\n  },\n  input: {\n    flex: 1,\n    fontSize: 15,\n    color: Colors.text,\n  },\n  errorBox: {\n    backgroundColor: Colors.danger + '12',\n    borderRadius: 10,\n    padding: 12,\n    marginBottom: 16,\n    borderWidth: 1,\n    borderColor: Colors.danger + '25',\n  },\n  errorText: {\n    color: Colors.danger,\n    fontSize: 13,\n    textAlign: 'center',\n    fontWeight: '500' as const,\n  },\n  submitButton: {\n    backgroundColor: Colors.primary,\n    borderRadius: 14,\n    paddingVertical: 16,\n    alignItems: 'center',\n    marginBottom: 16,\n  },\n  submitButtonDisabled: {\n    opacity: 0.7,\n  },\n  submitButtonText: {\n    color: Colors.white,\n    fontSize: 16,\n    fontWeight: '700' as const,\n  },\n  toggleButton: {\n    alignItems: 'center',\n    paddingVertical: 4,\n  },\n  toggleText: {\n    fontSize: 14,\n    color: Colors.textSecondary,\n  },\n  toggleTextBold: {\n    fontWeight: '700' as const,\n    color: Colors.primary,\n  },\n  infoSection: {\n    gap: 10,\n    paddingHorizontal: 8,\n  },\n  infoRow: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    gap: 10,\n  },\n  infoDot: {\n    width: 6,\n    height: 6,\n    borderRadius: 3,\n    backgroundColor: Colors.primary + '50',\n  },\n  infoText: {\n    fontSize: 13,\n    color: Colors.textSecondary,\n    flex: 1,\n  },\n});\n"
